<?php defined('BASEPATH') OR exit('No direct script access allowed'); include APPPATH . 'views/layouts/header.php'; include APPPATH . 'views/layouts/sidebar.php'; ?>
<div class="ami-panel"><div class="ami-panel-body"><h2 class="ami-section-title mb-4">Kapabilitas Organisasi</h2><div class="table-responsive"><table class="table ami-table"><thead><tr><th>Kapabilitas</th><?php foreach (Organization_service::ROLES as $role): ?><th><?php echo html_escape($role); ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($capabilities as $capability): ?><tr><td><strong><?php echo html_escape($capability->label); ?></strong><br><small><?php echo html_escape($capability->description); ?></small></td><?php foreach (Organization_service::ROLES as $role): ?><td><?php echo in_array($capability->code, $role_capabilities[$role], TRUE) ? '<i class="fas fa-check text-success" aria-label="Aktif"></i>' : '<span class="text-muted">-</span>'; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div>
<?php if ($can_manage_capabilities): ?><?php foreach (Organization_service::ROLES as $role): ?><?php echo form_open('lpmpi/organization/capabilities/update', ['class' => 'border-top pt-3 mt-3']); ?><input type="hidden" name="role" value="<?php echo html_escape($role); ?>"><h3 class="h5"><?php echo html_escape($role); ?></h3><?php foreach ($capabilities as $capability): ?><div class="form-check"><input class="form-check-input" type="checkbox" name="capability_ids[]" value="<?php echo (int) $capability->id; ?>" id="<?php echo html_escape($role . '_' . $capability->id); ?>" <?php echo in_array($capability->code, $role_capabilities[$role], TRUE) ? 'checked' : ''; ?>><label class="form-check-label" for="<?php echo html_escape($role . '_' . $capability->id); ?>"><?php echo html_escape($capability->label); ?></label></div><?php endforeach; ?><button class="btn btn-ami mt-2" type="submit">Simpan <?php echo html_escape($role); ?></button><?php echo form_close(); ?><?php endforeach; ?><?php endif; ?>
</div></div><?php include APPPATH . 'views/layouts/footer.php'; ?>
